solution:
.layout {
  min-height: 300px;
  border: 2px dashed #a1a1aa;
}

.sidebar {
  padding: 12px;
  background: #18181b;
  color: #fafafa;
}

.menu {
  margin: 0;
  padding-left: 16px;
}

.content {
  padding: 12px;
  background: #fed7aa;
  border: 1px solid #f97316;
  border-radius: 6px;
}

/* ---- Solution ---- */
.layout {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 16px;
}

@media (max-width: 500px) {
  .layout {
    grid-template-columns: 1fr;
  }
}
